#include <cstdio>
#include <unordered_map>
#include <queue>
#include <vector>
using namespace std;

class DualHeap {
private:
    priority_queue<int> low;
    priority_queue<int, vector<int>, greater<int>> high;
    unordered_map<int, int> removed;
    int lowCount = 0;
    int highCount = 0;

    template<typename T>
    void clean(T& heap) {
        while (!heap.empty() && removed[heap.top()] > 0) {
            removed[heap.top()]--;
            heap.pop();
        }
    }

    void balance() {
        if (lowCount > highCount + 1) {
            lowCount -= 1;
            highCount += 1;
            high.push(low.top());
            low.pop();
            clean(low);
        } else if (lowCount < highCount) {
            lowCount += 1;
            highCount -= 1;
            low.push(high.top());
            high.pop();
            clean(high);
        }
    }

public:
    void insert(int num) {
        if (low.empty() || num <= low.top()) {
            lowCount += 1;
            low.push(num);
        } else {
            highCount += 1;
            high.push(num);
        }
        balance();
    }

    void erase(int num) {
        removed[num]++;
        if (!low.empty() && num <= low.top()) {
            lowCount -= 1;
            clean(low);
        } else {
            highCount -= 1;
            clean(high);
        }
        balance();
    }

    double getMid() {
        if (lowCount == highCount) {
            return ((double)low.top() + high.top()) / 2.0;
        } else {
            return low.top();
        }
    }
};

class Solution {
public:
    vector<double> medianSlidingWindow(vector<int>& nums, int k) {
        DualHeap dualHeap;
        vector<double> res;
        for (int i = 0; i < k; i++) {
            dualHeap.insert(nums[i]);
        }
        res.push_back(dualHeap.getMid());
        for (int i = k; i < nums.size(); i++) {
            dualHeap.insert(nums[i]);
            dualHeap.erase(nums[i - k]);
            res.push_back(dualHeap.getMid());
        }
        return res;
    }
};
